#!/usr/bin/env bash
set -euo pipefail

# Build a native Debian package from an already-built Slickchook release.
# Database credentials are generated by the install helper at package install
# time; they are never stored in the package.
#
# The Caddy TLS certificate's hostname/port/expiry can be overridden at
# install time via CADDY_HOSTNAME, CADDY_LISTEN_PORT, and CADDY_CERT_DAYS.
# sudo resets most environment variables by default, so pass e.g.
# sudo --preserve-env=CADDY_HOSTNAME,CADDY_LISTEN_PORT,CADDY_CERT_DAYS apt
# install ./slickchook_*.deb, or run the install from a root shell directly.

readonly ROOT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
readonly VERSION=${SLICKCHOOK_VERSION:-$(sed -n 's/^version = "\([^"]*\)"/\1/p' "${ROOT_DIR}/Cargo.toml" | head -1)}
readonly ARCH=${SLICKCHOOK_ARCH:-$(dpkg --print-architecture)}
readonly OUT_DIR=${SLICKCHOOK_DEB_OUT:-${ROOT_DIR}/dist}
readonly PKG="${OUT_DIR}/slickchook_${VERSION}_${ARCH}"

[[ -x ${ROOT_DIR}/target/release/slickchook ]] || { echo "build release binaries first: cargo build --locked --release --bins" >&2; exit 1; }
[[ -x ${ROOT_DIR}/target/release/slickchook-runner ]] || { echo "missing slickchook-runner release binary" >&2; exit 1; }
command -v dpkg-deb >/dev/null || { echo "dpkg-deb is required" >&2; exit 1; }

rm -rf "${PKG}"
install -d -m 0755 "${PKG}/DEBIAN" "${PKG}/opt/slickchook" \
  "${PKG}/usr/local/sbin" "${PKG}/usr/share/slickchook" \
  "${PKG}/usr/share/doc/slickchook" "${PKG}/etc/systemd/system" \
  "${PKG}/etc/slickchook"

install -m 0755 "${ROOT_DIR}/target/release/slickchook" "${PKG}/opt/slickchook/slickchook"
install -m 0755 "${ROOT_DIR}/target/release/slickchook-runner" "${PKG}/opt/slickchook/slickchook-runner"
install -m 0755 "${ROOT_DIR}/scripts/slickchook-plugin" "${PKG}/usr/local/sbin/slickchook-plugin"
printf '%s\n' 'bind_addr = "127.0.0.1:8080"' > "${PKG}/etc/slickchook/slickchook.toml"
cp -a "${ROOT_DIR}/plugins" "${PKG}/usr/share/slickchook/"
cp -a "${ROOT_DIR}/migrations" "${PKG}/usr/share/slickchook/"
install -m 0644 "${ROOT_DIR}/deploy/slickchook.service" "${PKG}/etc/systemd/system/slickchook.service"
install -m 0644 RUNNER.md PLUGINS.md SECURITY_CONSIDERATIONS.md "${PKG}/usr/share/doc/slickchook/"

cat >"${PKG}/DEBIAN/control" <<EOF
Package: slickchook
Version: ${VERSION}
Section: net
Priority: optional
Architecture: ${ARCH}
Maintainer: Slickchook contributors
Depends: adduser, acl, docker.io | docker-ce, postgresql, postgresql-client
Description: MCP server for sandboxed reconnaissance plugins
 Slickchook runs reviewed containerized tools through a restricted runner.
EOF

cat >"${PKG}/DEBIAN/conffiles" <<'EOF'
/etc/slickchook/slickchook.toml
EOF

cat >"${PKG}/DEBIAN/postinst" <<'EOF'
#!/bin/sh
set -eu
getent group slickchook >/dev/null 2>&1 || addgroup --system slickchook
id slickchook >/dev/null 2>&1 || adduser --system --ingroup slickchook --home /var/lib/slickchook --no-create-home --shell /usr/sbin/nologin slickchook
install -d -o root -g root -m 0755 /opt/slickchook
install -d -o root -g slickchook -m 0750 /etc/slickchook /var/lib/slickchook/plugins
install -d -o slickchook -g slickchook -m 0750 /var/lib/slickchook/artifacts
if [ ! -e /etc/slickchook/slickchook.toml ]; then printf '%s\n' 'bind_addr = "127.0.0.1:8080"' > /etc/slickchook/slickchook.toml; fi
chown root:slickchook /etc/slickchook/slickchook.toml
chmod 0640 /etc/slickchook/slickchook.toml
systemctl enable --now postgresql.service
runuser -u postgres -- psql -tAc "SELECT 1 FROM pg_roles WHERE rolname='slickchook'" | grep -q 1 || runuser -u postgres -- createuser --no-createdb --no-createrole --no-superuser slickchook
runuser -u postgres -- psql -tAc "SELECT 1 FROM pg_database WHERE datname='slickchook_db'" | grep -q 1 || runuser -u postgres -- createdb -O slickchook slickchook_db
runuser -u postgres -- psql -c "ALTER DATABASE slickchook_db OWNER TO slickchook" >/dev/null
if [ ! -e /etc/slickchook/postgres.env ]; then
  pw=$(od -An -N24 -tx1 /dev/urandom | tr -d ' \n')
  runuser -u postgres -- psql -c "ALTER ROLE slickchook PASSWORD '${pw}'" >/dev/null
  printf 'DATABASE_URL=postgresql://slickchook:%s@127.0.0.1:5432/slickchook_db\n' "$pw" > /etc/slickchook/postgres.env
  chown root:slickchook /etc/slickchook/postgres.env
  chmod 0640 /etc/slickchook/postgres.env
fi
systemctl daemon-reload
systemctl enable slickchook.service >/dev/null
systemctl restart slickchook.service || systemctl start slickchook.service

# Front slickchook with Caddy for TLS. CADDY_HOSTNAME is the hostname the
# certificate is issued for and connecting clients must resolve and use --
# TLS servers pick a certificate by the ClientHello's SNI, and clients don't
# send SNI for literal IP addresses, so a certificate lookup by IP alone
# fails the handshake outright. The certificate is generated once and left
# in place on upgrade/reinstall: regenerating it would silently break
# certificate pinning on whatever client (e.g. a paired AI-agent instance)
# was handed its fingerprint at provisioning time. Delete
# /etc/caddy/tls/server.{crt,key} manually to force reissuance.
CADDY_HOSTNAME="${CADDY_HOSTNAME:-slickchook}"
CADDY_LISTEN_PORT="${CADDY_LISTEN_PORT:-8443}"
CADDY_CERT_DAYS="${CADDY_CERT_DAYS:-365}"
if ! command -v caddy >/dev/null 2>&1; then
  if ! apt-get install --yes caddy; then
    # Older Ubuntu/Debian releases don't carry caddy in their default repos;
    # fall back to Caddy's official apt repository.
    # https://caddyserver.com/docs/install#debian-ubuntu-raspbian
    apt-get install --yes debian-keyring debian-archive-keyring apt-transport-https
    curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/gpg.key' \
      | gpg --dearmor -o /usr/share/keyrings/caddy-stable-archive-keyring.gpg
    curl -1sLf 'https://dl.cloudsmith.io/public/caddy/stable/debian.deb.txt' \
      > /etc/apt/sources.list.d/caddy-stable.list
    apt-get update
    apt-get install --yes caddy
  fi
fi
install -d -o root -g root -m 0755 /etc/caddy/tls
if [ ! -e /etc/caddy/tls/server.crt ] || [ ! -e /etc/caddy/tls/server.key ]; then
  openssl req -new -x509 -days "${CADDY_CERT_DAYS}" -nodes \
    -out /etc/caddy/tls/server.crt -keyout /etc/caddy/tls/server.key \
    -subj "/CN=${CADDY_HOSTNAME}" \
    -addext "subjectAltName=DNS:${CADDY_HOSTNAME}" \
    -addext "basicConstraints=critical,CA:FALSE" \
    -addext "keyUsage=critical,digitalSignature,keyEncipherment" \
    -addext "extendedKeyUsage=serverAuth"
fi
chown root:caddy /etc/caddy/tls/server.key
chmod 0640 /etc/caddy/tls/server.key
chmod 0644 /etc/caddy/tls/server.crt
# reverse_proxy targets slickchook's bind_addr default (127.0.0.1:8080). If
# bind_addr is later customized in /etc/slickchook/slickchook.toml, update
# this target to match.
cat > /etc/caddy/Caddyfile <<EOF2
{
  auto_https off
}
${CADDY_HOSTNAME}:${CADDY_LISTEN_PORT} {
  tls /etc/caddy/tls/server.crt /etc/caddy/tls/server.key
  reverse_proxy 127.0.0.1:8080
}
EOF2
systemctl enable --now caddy.service
systemctl reload caddy.service || systemctl restart caddy.service
echo "MCP endpoint (via Caddy, TLS): https://${CADDY_HOSTNAME}:${CADDY_LISTEN_PORT}/sse"
echo "Connecting clients must resolve '${CADDY_HOSTNAME}' to this host and trust"
echo "exactly this certificate, pinned at provisioning time:"
echo "  /etc/caddy/tls/server.crt"
openssl x509 -in /etc/caddy/tls/server.crt -noout -fingerprint -sha256
EOF
chmod 0755 "${PKG}/DEBIAN/postinst"

cat >"${PKG}/DEBIAN/prerm" <<'EOF'
#!/bin/sh
set -eu
if [ "${1:-}" = remove ] || [ "${1:-}" = deconfigure ]; then systemctl stop slickchook.service || true; fi
EOF
chmod 0755 "${PKG}/DEBIAN/prerm"

mkdir -p "${OUT_DIR}"
dpkg-deb --build --root-owner-group "${PKG}" "${OUT_DIR}/slickchook_${VERSION}_${ARCH}.deb"
rm -rf "${PKG}"
echo "built ${OUT_DIR}/slickchook_${VERSION}_${ARCH}.deb"
